46	function readiness(): Readonly<{ readonly missing: readonly string[]; readonly ready: boolean }> {
47		const missing = REQUIRED_NODE_OWNERS.filter((owner) => {
48			const filename = resolve(REPOSITORY_ROOT, owner);
49			if (!existsSync(filename)) return true;
50			const value = readFileSync(filename, "utf8");
51			return owner.endsWith("maintenance.ts")
52				? !value.includes("resolveNodeAheReclamationMaintenance")
53				: !value.includes("reclaimClosedEpoch");
54		});
