637					const { input } = await fiveGenerationInput(store);
638					await store.close();
639					closed = true;
640					const closedPromise = maintenance.reclaimClosedEpoch(input);
641					expect(closedPromise).toBeInstanceOf(Promise);
642					expect(await rejectedCode(() => closedPromise)).toBe("AHE_RECLAMATION_STORE_CLOSED");
643					expect(await rejectedCode(() => maintenance.reclaimClosedEpoch({}))).toBe("AHE_RECLAMATION_INVALID_ARGUMENT");
644				} finally {
645					if (!closed) await store.close();
646				}
647			}
648		);
649	
650		it.skipIf(!state.ready).each([...D109C_LINEAGE_MUTANTS, ...D109C_CORRUPTION_MUTANTS, ...D109C_COUNT_MUTANTS])(
651			"refuses the frozen native mutant %s with zero committed deletion",
652			async (mutant) => {
653				const { filename, instrumentation, maintenance, store } = await opened(mutant);
654				try {
655					const { input } = await fiveGenerationInput(store);
656					let request = mutableRequest(input);
657					let code = "AHE_RECLAMATION_CORRUPT";
658					if ((D109C_COUNT_MUTANTS as readonly string[]).includes(mutant)) {
659						instrumentation.installNodeAheReclamationCountFault(store, countFault(mutant));
660					} else {
661						({ code, request } = applyLineageOrCorruptionMutant(filename, input, mutant));
662					}
663					const before = databaseImage(filename);
664					expect(await rejectedCode(() => maintenance.reclaimClosedEpoch(request))).toBe(code);
665					expect(databaseImage(filename)).toBe(before);
666					const ordinary = await store.readHead(D109C_OBJECT);
667					if (code === "AHE_RECLAMATION_CORRUPT") {
668						expect(ordinary).toEqual({ ok: false, reason: "STORE_POISONED" });
669					} else {
670						expect(ordinary.ok).toBe(true);
671					}
672				} finally {
673					await store.close();
674				}
675			}
676		);
677	
678		it.skipIf(!state.ready).each(D109C_REFERENCE_CASES)("proves the frozen native reference case %s", async (caseId) => {
679			const { filename, maintenance, store } = await opened(caseId);
680			try {
681				const fixture = await fiveGenerationInput(store, (index) =>
682					caseId === "retained-shared-blob" && index === 3
683						? Uint8Array.of(1, 2, 3)
684						: Uint8Array.of(index, index + 1, index + 2)
685				);
686				const firstDigest = fixture.records.find(({ generationId }) => generationId === d109cGenerationId(1))?.closure[0]
687					?.digest;
688				const secondDigest = fixture.records.find(({ generationId }) => generationId === d109cGenerationId(2))?.closure[0]
689					?.digest;
690				if (firstDigest === undefined || secondDigest === undefined)
691					throw new TypeError("D109C_REFERENCE_DIGEST_MISSING");
692				if (caseId === "cross-object-shared-blob") {
693					await addOtherGeneration(store, {
694						closure: [{ byteLength: 3, digest: firstDigest }],
695						complete: true,
696						promote: [firstDigest],
697					});
698				} else if (caseId === "unrelated-orphan-retained") {
699					const bytes = Uint8Array.of(240, 241, 242);
700					const digest = successful(digestBlob(bytes), "ORPHAN_DIGEST");
701					withDatabase(filename, (database) => {
702						database.prepare("INSERT INTO blobs(digest,bytes) VALUES (?,?)").run(digest, bytes);
703					});
704				} else if (caseId === "staged-partial-promotions" || caseId === "discarded-partial-promotions") {
705					await addOtherGeneration(store, {
706						closure: [
707							{ byteLength: 3, digest: firstDigest },
708							{ byteLength: 3, digest: secondDigest },
709						].sort((left, right) => left.digest.localeCompare(right.digest)),
710						discard: caseId === "discarded-partial-promotions",
711						promote: [firstDigest],
712					});
713				}
714				const blobCountBefore = withDatabase(filename, (database) =>
715					Number((database.prepare("SELECT COUNT(*) AS count FROM blobs").get() as { count: number }).count)
716				);
717				const receipt = await maintenance.reclaimClosedEpoch(fixture.input);
718				expect(receipt.deletedGenerationIds).toEqual([d109cGenerationId(1), d109cGenerationId(2)]);
719				if (
720					caseId === "retained-shared-blob" ||
721					caseId === "cross-object-shared-blob" ||
722					caseId === "staged-partial-promotions" ||
723					caseId === "discarded-partial-promotions"
724				) {
725					expect(blobBytes(filename, firstDigest)).toEqual(Uint8Array.of(1, 2, 3));
726				} else if (caseId === "candidate-only-blob") {
727					expect(blobBytes(filename, firstDigest)).toBeUndefined();
728					expect(blobBytes(filename, secondDigest)).toBeUndefined();
729				} else {
730					const blobCountAfter = withDatabase(filename, (database) =>
731						Number((database.prepare("SELECT COUNT(*) AS count FROM blobs").get() as { count: number }).count)
732					);
733					expect(blobCountAfter).toBe(blobCountBefore - 2);
734				}
735			} finally {
736				await store.close();
737			}
738		});
739	
740		it.skipIf(!state.ready)("owns six genuine SIGKILL edges with old XOR complete-new reopen state", async () => {
741			expect(D109C_CRASH_EDGES).toEqual([
742				"after-floor-rewrite",
743				"after-promotion-delete",
744				"after-generation-delete",
745				"after-blob-delete",
746				"before-commit",
747				"after-commit",
748			]);
749			for (const edge of D109C_CRASH_EDGES) {
750				const filename = databaseFilename(`sigkill-${edge}`);
751				await hardKillAt(filename, edge);
752				const shape = reopenedShape(filename);
753				expect(shape.integrity).toBe("ok");
754				expect(shape.headGenerationId).toBe(d109cGenerationId(5));
755				const old =
756					shape.generationIds.length === 5 && !shape.floorNormalized && shape.promotions === 5 && shape.blobs === 5;
757				const completeNew =
758					shape.generationIds.join(",") ===
759						d109cGenerationId(3) + "," + d109cGenerationId(4) + "," + d109cGenerationId(5) &&
760					shape.floorNormalized &&
761					shape.promotions === 3 &&
762					shape.blobs === 3;
763				expect(Number(old) + Number(completeNew)).toBe(1);
764				expect(completeNew).toBe(edge === "after-commit");
765			}
766		});
767	});
