45	function record(value: unknown): Record<string, unknown> {
46		if (value === null || typeof value !== "object" || Array.isArray(value)) {
47			throw new TypeError("D109D_TEST_RECORD_EXPECTED");
48		}
49		return value as Record<string, unknown>;
50	}
51	
