56	
57	function changedDigest(value: unknown): string {
58		return value === "f".repeat(64) ? "e".repeat(64) : "f".repeat(64);
59	}
60	
61	async function eventually(check: () => Promise<boolean>, attempts = 100): Promise<void> {
62		for (let attempt = 0; attempt < attempts; attempt += 1) {
63			if (await check()) return;
64			await new Promise<void>((resolvePromise) => setTimeout(resolvePromise, 10));
65		}
66		throw new TypeError("D109D_EVENTUALLY_TIMED_OUT");
67	}
68	
69	async function reclaim(
70		fixture: Awaited<ReturnType<typeof openD109dHotFixture>>,
71		receipts: Awaited<ReturnType<typeof createD109dReceipts>>,
72		options: Readonly<{
73			readonly aheReceipt?: unknown;
74			readonly issuanceReceipt?: unknown;
75			readonly successor?: object;
76		}> = {}
77	): Promise<Readonly<Record<string, unknown>>> {
78		const candidate = await d109dCandidate();
79		if (candidate.reclaimInstalledV3Runtime === undefined) throw new TypeError("D109D_CANDIDATE_MISSING");
80		return candidate.reclaimInstalledV3Runtime({
81			aheReceipt: options.aheReceipt ?? receipts.aheReceipt,
82			issuanceReceipt: options.issuanceReceipt ?? receipts.issuanceReceipt,
83			successor: options.successor ?? fixture.successor,
84		});
