230		public close(): Promise<void> {
231			if (!this.closed) {
232				this.closed = true;
233				this.recoveryCertificates.clear();
234				this.connection.close();
235			}
236			return Promise.resolve();
237		}
238	
239		private run(command: unknown): Promise<StoreResult<unknown>> {
240			const prepared = prepareStorageAdapterCommand(command);
241			if (!prepared.ok) return Promise.resolve(prepared);
242			if (this.closed) {
243				return Promise.resolve(evaluateStorageAdapterCommand(prepared.value, [{ kind: "store-closed" }]).result);
244			}
245			if (this.poisoned) return Promise.resolve({ ok: false, reason: "STORE_POISONED" });
246			return Promise.resolve(this.execute(prepared.value));
247		}
248	
249		private execute(prepared: PreparedStorageAdapterCommand): StoreResult<unknown> {
250			const operation = prepared.command.kind;
251			const mutation = isMutation(operation);
252			let transactionActive = false;
253			let result: StoreResult<unknown>;
254			try {
255				if (mutation) {
256					this.connection.exec("BEGIN IMMEDIATE");
257					transactionActive = true;
258					if (!("objectId" in prepared.command)) throw new Error("mutation command lacks object scope");
259					const recovered = this.ensureCertificate(
260						prepared.command.objectId,
261						operation === "completeGeneration" || operation === "swapHead"
262					);
263					if (!recovered.ok) {
264						this.poisoned = true;
265						this.connection.exec("ROLLBACK");
266						transactionActive = false;
267						return recovered;
268					}
269				}
270				const facts = this.loadFacts(prepared);
271				let evaluation = evaluateStorageAdapterCommand(prepared, facts);
272				if (prepared.command.kind === "completeGeneration" || prepared.command.kind === "swapHead") {
273					if (!evaluation.result.ok && evaluation.result.reason !== "INVALID_ARGUMENT") {
274						this.connection.exec("ROLLBACK");
275						transactionActive = false;
276						return evaluation.result;
277					}
278					const authorization = this.verifyCandidate(prepared.command.objectId, prepared.command.generationId, facts);
279					if (authorization === undefined || !authorization.ok) {
280						this.connection.exec("ROLLBACK");
281						transactionActive = false;
282						return authorization ?? { ok: false, reason: "INVALID_ARGUMENT" };
283					}
284					evaluation = evaluateStorageAdapterCommand(prepared, facts, authorization.value);
285				}
286				if (!evaluation.result.ok) {
287					if (transactionActive) {
288						this.connection.exec("ROLLBACK");
289						transactionActive = false;
290					}
291					return evaluation.result;
292				}
293				if (mutation) {
294					this.applyWrites(evaluation, operation);
295					if (this.crashObserver === undefined) {
296						if (operation === "beginGeneration") this.fault?.({ operation, edge: "before-commit" });
297					} else {
298						this.crashObserver({ operation, edge: "before-commit" });
299					}
300				}
301				if (transactionActive) {
302					this.connection.exec("COMMIT");
303					transactionActive = false;
304				}
305				result = evaluation.result;
306				if (mutation && operation === "swapHead" && result.ok) {
307					const swap = result.value as Readonly<{ head: PresentHead }>;
308					this.recoveryCertificates.set(prepared.command.objectId, headFingerprint(swap.head));
309				}
310			} catch (cause) {
311				this.recoveryCertificates.clear();
312				const persistedReason = cause instanceof PersistedStorageError ? cause.reason : undefined;
313				if (persistedReason !== undefined) this.poisoned = true;
314				if (transactionActive) {
315					try {
316						this.connection.exec("ROLLBACK");
317					} catch {
318						// The primary substrate failure remains the public cause.
319					}
320				}
321				return persistedReason === undefined
322					? { ok: false, reason: "SUBSTRATE_FAILURE", cause }
323					: { ok: false, reason: persistedReason };
324			}
325			if (mutation) this.crashObserver?.({ operation, edge: "after-commit" });
326			return result;
327		}
328	
329		private loadFacts(prepared: PreparedStorageAdapterCommand): readonly StorageAdapterFact[] {
330			const facts: StorageAdapterFact[] = [];
331			const loadedBlobs = new Set<BlobDigest>();
332			const loadedPromotions = new Set<string>();
333			for (const requirement of prepared.requirements) {
334				switch (requirement.kind) {
335					case "head": {
336						const row = this.connection
337							.prepare("SELECT head_record FROM objects WHERE object_id = ?")
338							.get(requirement.objectId) as DatabaseRow | undefined;
339						const classified = classifyPersistedState({
340							kind: "head",
341							objectId: requirement.objectId,
342							row: row === undefined ? null : { objectId: requirement.objectId, record: row.head_record },
343						});
344						if (!classified.ok) throw new PersistedStorageError(classified.reason);
345						if (classified.value.kind !== "head") throw new Error("persisted classifier returned the wrong fact kind");
346						facts.push({
347							headRecord: classified.value.record,
348							kind: "head",
349							objectId: requirement.objectId,
350						});
351						break;
352					}
353					case "generation-page": {
354						const rows = (
355							requirement.afterGenerationId === null
356								? this.connection
357										.prepare(
358											"SELECT generation_id, record FROM generations WHERE object_id = ? ORDER BY generation_id LIMIT ?"
359										)
360										.all(requirement.objectId, requirement.limitPlusOne)
361								: this.connection
362										.prepare(
363											"SELECT generation_id, record FROM generations WHERE object_id = ? AND generation_id > ? ORDER BY generation_id LIMIT ?"
364										)
365										.all(requirement.objectId, requirement.afterGenerationId, requirement.limitPlusOne)
366						) as DatabaseRow[];
367						facts.push({
368							afterGenerationId: requirement.afterGenerationId,
369							generationRecords: rows.map((row) => boundGenerationRecord(row, requirement.objectId)),
370							kind: "generation-page",
371							objectId: requirement.objectId,
372						});
373						break;
374					}
375					case "generation":
376						this.loadGeneration(requirement.objectId, requirement.generationId, facts);
377						break;
378					case "blob":
379						this.loadBlob(requirement.digest, facts, loadedBlobs);
380						break;
381					case "promotion":
382						this.loadPromotion(requirement, facts, loadedPromotions);
383						break;
384				}
385			}
386			if (prepared.command.kind === "swapHead") {
387				const headFact = facts.find(
388					(fact): fact is Extract<StorageAdapterFact, { kind: "head" }> => fact.kind === "head"
389				);
390				const decoded =
391					headFact?.headRecord === null || headFact === undefined ? undefined : decodeHeadRecordV1(headFact.headRecord);
392				if (
393					decoded?.ok === true &&
394					decoded.value.kind === "present" &&
395					decoded.value.generationId !== prepared.command.generationId
396				)
397					this.loadGeneration(prepared.command.objectId, decoded.value.generationId, facts);
398			}
399			return facts;
400		}
401		private loadGeneration(objectId: StorageObjectId, generationId: GenerationId, facts: StorageAdapterFact[]): void {
402			const row = this.connection
403				.prepare("SELECT record FROM generations WHERE object_id = ? AND generation_id = ?")
404				.get(objectId, generationId) as DatabaseRow | undefined;
405			if (row === undefined) {
406				facts.push({ kind: "generation", objectId, generationId, generationRecord: null });
407				return;
408			}
409			const classified = classifyPersistedState({
410				kind: "generation",
411				objectId,
412				row: { objectId, generationId, record: row.record },
413			});
414			if (!classified.ok) throw new PersistedStorageError(classified.reason);
415			if (classified.value.kind !== "generation") throw new Error("persisted classifier returned wrong kind");
416			facts.push({ kind: "generation", objectId, generationId, generationRecord: classified.value.record });
417		}
418	
419		private loadBlob(digest: BlobDigest, facts: StorageAdapterFact[], loaded: Set<BlobDigest>): void {
420			if (loaded.has(digest)) return;
421			const row = this.connection.prepare("SELECT bytes FROM blobs WHERE digest = ?").get(digest) as
422				| DatabaseRow
423				| undefined;
424			facts.push({ kind: "blob", digest, bytes: row === undefined ? null : databaseBytes(row.bytes) });
425			loaded.add(digest);
426		}
427	
428		private loadPromotion(
429			scope: Readonly<{ objectId: StorageObjectId; generationId: GenerationId; digest: BlobDigest }>,
430			facts: StorageAdapterFact[],
431			loaded: Set<string>
432		): void {
433			const key = `${scope.objectId}\0${scope.generationId}\0${scope.digest}`;
434			if (loaded.has(key)) return;
435			const row = this.connection
436				.prepare("SELECT 1 FROM promotions WHERE object_id = ? AND generation_id = ? AND digest = ?")
437				.get(scope.objectId, scope.generationId, scope.digest);
438			if (row !== undefined) facts.push({ kind: "promotion", ...scope });
439			loaded.add(key);
440		}
441	
442		private recoverTransaction(objectId: StorageObjectId): StoreResult<ActiveGenerationSnapshot> {
443			let active = false;
444			try {
445				this.connection.exec("BEGIN IMMEDIATE");
446				active = true;
447				const result = this.recoverWithinTransaction(objectId);
448				if (!result.ok) {
449					this.poisoned = true;
450					this.connection.exec("ROLLBACK");
451					active = false;
452					return result;
453				}
454				this.connection.exec("COMMIT");
455				active = false;
456				const snapshot = freezeRecoverySnapshot(result.value);
457				this.recoveryCertificates.set(objectId, headFingerprint(snapshot.head));
458				return { ok: true, value: snapshot };
459			} catch (cause) {
460				this.recoveryCertificates.clear();
461				if (active)
462					try {
463						this.connection.exec("ROLLBACK");
464					} catch {
465						/* preserve cause */
466					}
467				return { ok: false, reason: "SUBSTRATE_FAILURE", cause };
468			}
469		}
470	
471		private ensureCertificate(objectId: StorageObjectId, required: boolean): StoreResult<undefined> {
472			const head = this.readHeadWithinTransaction(objectId);
473			if (!head.ok) return head;
474			if (this.recoveryCertificates.get(objectId) === headFingerprint(head.value)) return { ok: true, value: undefined };
475			if (!required && !this.recoveryCertificates.has(objectId)) return { ok: true, value: undefined };
476			const recovered = this.recoverWithinTransaction(objectId);
477			if (!recovered.ok) return recovered;
478			this.recoveryCertificates.set(objectId, headFingerprint(recovered.value.head));
479			return { ok: true, value: undefined };
480		}
481	
482		private readHeadWithinTransaction(objectId: StorageObjectId): StoreResult<ExpectedHead> {
483			const row = this.connection.prepare("SELECT head_record FROM objects WHERE object_id = ?").get(objectId) as
484				| DatabaseRow
485				| undefined;
486			const classified = classifyPersistedState({
487				kind: "head",
488				objectId,
489				row: row === undefined ? null : { objectId, record: row.head_record },
490			});
491			return classified.ok && classified.value.kind === "head"
492				? { ok: true, value: classified.value.head }
493				: (classified as StoreResult<ExpectedHead>);
494		}
495	
496		private recoverWithinTransaction(objectId: StorageObjectId): StoreResult<ActiveGenerationSnapshot> {
497			const headResult = this.readHeadWithinTransaction(objectId);
498			if (!headResult.ok) return headResult;
499			let after: string | null = null;
500			let adopted: GenerationRecord | null = null;
501			let adoptedCount = 0;
502			let failure: "NON_CANONICAL_RECORD" | "UNSUPPORTED_STORAGE_SCHEMA" | undefined;
503			for (;;) {
504				const rows = (
505					after === null
506						? this.connection
507								.prepare(
508									"SELECT generation_id, record FROM generations WHERE object_id = ? ORDER BY generation_id LIMIT ?"
509								)
510								.all(objectId, 129)
511						: this.connection
512								.prepare(
513									"SELECT generation_id, record FROM generations WHERE object_id = ? AND generation_id > ? ORDER BY generation_id LIMIT ?"
514								)
515								.all(objectId, after, 129)
516				) as DatabaseRow[];
517				for (const row of rows) {
518					const classified = classifyPersistedState({
519						kind: "generation",
520						objectId,
521						row: { objectId, generationId: row.generation_id, record: row.record },
522					});
523					if (!classified.ok)
524						failure =
525							failure === "UNSUPPORTED_STORAGE_SCHEMA" || classified.reason === "UNSUPPORTED_STORAGE_SCHEMA"
526								? "UNSUPPORTED_STORAGE_SCHEMA"
527								: "NON_CANONICAL_RECORD";
528					else if (classified.value.kind === "generation" && classified.value.generation.state === "Adopted") {
529						adoptedCount++;
530						adopted ??= classified.value.generation;
531					}
532				}
533				if (rows.length < 129) break;
534				const cursor = rows.at(-1)?.generation_id;
535				if (typeof cursor !== "string") return { ok: false, reason: "NON_CANONICAL_RECORD" };
536				const parsedCursor = parseGenerationId(cursor);
537				if (!parsedCursor.ok) return { ok: false, reason: "NON_CANONICAL_RECORD" };
538				after = parsedCursor.value;
539			}
540			if (failure !== undefined) return { ok: false, reason: failure };
541			const head = headResult.value;
542			if (head.kind === "none")
543				return adoptedCount === 0
544					? {
545							ok: true,
546							value: { kind: "empty", head, adoptedGeneration: null, recomputedClosureDigest: null, references: [] },
547						}
548					: { ok: false, reason: "NON_CANONICAL_RECORD" };
549			if (
550				adoptedCount !== 1 ||
551				adopted === null ||
552				adopted.generationId !== head.generationId ||
553				adopted.closureDigest !== head.closureDigest
554			)
555				return { ok: false, reason: "NON_CANONICAL_RECORD" };
556			const verified = this.verifyClosure(objectId, adopted, "adopted");
557			if (!verified.ok) return verified;
558			return {
559				ok: true,
560				value: {
561					kind: "active",
562					head: { ...head },
563					adoptedGeneration: {
564						...adopted,
565						baseExpectedHead: { ...adopted.baseExpectedHead },
566						closure: adopted.closure.map((r) => ({ ...r })),
567					},
568					recomputedClosureDigest: adopted.closureDigest,
569					references: adopted.closure.map((r) => ({ ...r })),
570				},
571			};
572		}
