616		private applyWrites(evaluation: StorageAdapterEvaluation, operation: SqliteMutationOperation): void {
617			const occurrences = new Map<SqliteMutationStatement, number>();
618			const observe = (statement: SqliteMutationStatement): void => {
619				if (this.crashObserver === undefined) return;
620				const occurrence = (occurrences.get(statement) ?? 0) + 1;
621				occurrences.set(statement, occurrence);
622				this.crashObserver({ edge: "after-statement", occurrence, operation, statement });
623			};
624			for (const write of evaluation.writes) this.applyWrite(write, observe);
625		}
626	
627		private applyWrite(write: StorageAdapterWrite, observe: (statement: SqliteMutationStatement) => void): void {
628			switch (write.kind) {
629				case "replace-generation": {
630					const decoded = decodeGenerationRecordV1(write.record);
631					if (
632						!decoded.ok ||
633						decoded.value.objectId !== write.objectId ||
634						decoded.value.generationId !== write.generationId
635					) {
636						throw new Error("adapter emitted an invalid generation write");
637					}
638					this.connection
639						.prepare("INSERT OR IGNORE INTO objects(object_id, head_record) VALUES (?, NULL)")
640						.run(write.objectId);
641					observe("object-ensure");
642					const exists = this.connection
643						.prepare("SELECT 1 FROM generations WHERE object_id = ? AND generation_id = ?")
644						.get(write.objectId, write.generationId);
645					const statement =
646						exists === undefined
647							? this.connection.prepare("INSERT INTO generations(object_id, generation_id, record) VALUES (?, ?, ?)")
648							: this.connection.prepare("UPDATE generations SET record = ? WHERE object_id = ? AND generation_id = ?");
649					const result =
650						exists === undefined
651							? statement.run(write.objectId, write.generationId, new Uint8Array(write.record))
652							: statement.run(new Uint8Array(write.record), write.objectId, write.generationId);
653					observe(exists === undefined ? "generation-insert" : "generation-update");
654					requireOneChange(result.changes, "generation write");
655					return;
656				}
657				case "replace-head": {
658					const decoded = decodeHeadRecordV1(write.record);
659					if (!decoded.ok || decoded.value.kind !== "present" || decoded.value.objectId !== write.objectId) {
660						throw new Error("adapter emitted an invalid head write");
661					}
662					const result = this.connection
663						.prepare(
664							"INSERT INTO objects(object_id, head_record) VALUES (?, ?) " +
665								"ON CONFLICT(object_id) DO UPDATE SET head_record = excluded.head_record"
666						)
667						.run(write.objectId, new Uint8Array(write.record));
668					observe("head-upsert");
669					requireOneChange(result.changes, "head write");
670					return;
671				}
672				case "insert-blob": {
673					const result = this.connection
674						.prepare("INSERT INTO blobs(digest, bytes) VALUES (?, ?)")
675						.run(write.digest, new Uint8Array(write.bytes));
676					observe("blob-insert");
677					requireOneChange(result.changes, "blob insert");
678					return;
679				}
680				case "insert-promotion": {
681					const result = this.connection
682						.prepare("INSERT INTO promotions(object_id, generation_id, digest) VALUES (?, ?, ?)")
683						.run(write.objectId, write.generationId, write.digest);
684					observe("promotion-insert");
685					requireOneChange(result.changes, "promotion insert");
686				}
687			}
688		}
689	}
