691	function isMutation(kind: StorageAdapterCommand["kind"]): kind is SqliteMutationOperation {
692		return kind !== "readHead" && kind !== "readGenerationPage" && kind !== "getBlob";
693	}
694	
695	function headFingerprint(head: ExpectedHead): string {
696		return head.kind === "none"
697			? `none\0${head.objectId}`
698			: `present\0${head.objectId}\0${head.generationId}\0${head.revision}\0${head.closureDigest}`;
699	}
700	
701	function commandWithKind(kind: StorageAdapterCommand["kind"], input: unknown): unknown {
702		if (typeof input !== "object" || input === null || Array.isArray(input)) return { kind, invalidInput: input };
703		const descriptors = Object.getOwnPropertyDescriptors(input);
704		if (Object.prototype.hasOwnProperty.call(descriptors, "kind")) return { kind, invalidInput: true };
705		const command = { kind } as Record<PropertyKey, unknown>;
706		Object.defineProperties(command, descriptors);
707		return command;
708	}
709	
710	function databaseBytes(value: unknown): Uint8Array {
711		if (!(value instanceof Uint8Array)) throw new Error("SQLite returned a non-BLOB value");
712		return new Uint8Array(value);
713	}
714	
715	function boundGenerationRecord(row: DatabaseRow, objectId: StorageObjectId): Uint8Array {
716		const classified = classifyPersistedState({
717			kind: "generation",
718			objectId,
719			row: { generationId: row.generation_id, objectId, record: row.record },
720		});
721		if (!classified.ok) throw new PersistedStorageError(classified.reason);
722		if (classified.value.kind !== "generation") throw new Error("persisted classifier returned the wrong fact kind");
723		return classified.value.record;
724	}
