726	function requireOneChange(changes: number | bigint, label: string): void {
727		if (Number(changes) !== 1) throw new Error(`${label} did not affect exactly one row`);
728	}
729	
730	function hasExpectedPhysicalSchema(connection: DatabaseSync): boolean {
731		const tables = connection
732			.prepare("SELECT name FROM sqlite_schema WHERE type = 'table' AND name NOT LIKE 'sqlite_%' ORDER BY name")
733			.all() as DatabaseRow[];
734		const expectedNames = Object.keys(EXPECTED_COLUMNS).sort();
735		if (tables.length !== expectedNames.length || tables.some((row, index) => row.name !== expectedNames[index])) {
736			return false;
737		}
738		for (const tableName of expectedNames as (keyof typeof EXPECTED_COLUMNS)[]) {
739			const columns = connection.prepare(`PRAGMA table_info("${tableName}")`).all() as DatabaseRow[];
740			const expectedColumns = EXPECTED_COLUMNS[tableName];
741			if (
742				columns.length !== expectedColumns.length ||
743				columns.some((column, index) => {
744					const expected = expectedColumns[index];
745					return (
746						expected === undefined ||
747						column.name !== expected.name ||
748						column.type !== expected.type ||
749						Number(column.notnull) !== expected.notnull ||
750						Number(column.pk) !== expected.pk ||
751						column.dflt_value !== null
752					);
753				})
754			) {
755				return false;
756			}
757			const foreignKeyColumns = (connection.prepare(`PRAGMA foreign_key_list("${tableName}")`).all() as DatabaseRow[])
758				.map((row) => `${String(row.table)}:${String(row.from)}:${String(row.to)}`)
759				.sort();
760			const expectedForeignKeyColumns = [...EXPECTED_FOREIGN_KEY_COLUMNS[tableName]].sort();
761			if (
762				foreignKeyColumns.length !== expectedForeignKeyColumns.length ||
763				foreignKeyColumns.some((value, index) => value !== expectedForeignKeyColumns[index])
764			) {
765				return false;
766			}
767		}
768		return true;
769	}
770	
771	function configureConnection(connection: DatabaseSync): void {
772		connection.exec("PRAGMA busy_timeout = 1000");
773		connection.exec("PRAGMA foreign_keys = ON");
774		const tableCount = (
775			connection
776				.prepare("SELECT count(*) AS count FROM sqlite_schema WHERE type = 'table' AND name NOT LIKE 'sqlite_%'")
777				.get() as DatabaseRow
778		).count;
779		if (Number(tableCount) === 0) {
780			connection.exec("BEGIN IMMEDIATE");
781			try {
782				connection.exec(SCHEMA);
783				if (!hasExpectedPhysicalSchema(connection)) throw new PersistedStorageError("UNSUPPORTED_STORAGE_SCHEMA");
784				connection.exec("COMMIT");
785			} catch (error) {
786				try {
787					connection.exec("ROLLBACK");
788				} catch {
789					// Preserve the primary schema-creation failure.
790				}
791				throw error;
792			}
793		}
794		if (!hasExpectedPhysicalSchema(connection)) throw new PersistedStorageError("UNSUPPORTED_STORAGE_SCHEMA");
795		connection.exec("PRAGMA journal_mode = WAL");
796		connection.exec("PRAGMA synchronous = FULL");
797	}
