799	function freezeRecoverySnapshot(snapshot: ActiveGenerationSnapshot): ActiveGenerationSnapshot {
800		if (snapshot.kind === "empty")
801			return Object.freeze({
802				...snapshot,
803				head: Object.freeze({ ...snapshot.head }),
804				references: Object.freeze([] as []),
805			});
806		return Object.freeze({
807			...snapshot,
808			head: Object.freeze({ ...snapshot.head }),
809			adoptedGeneration: Object.freeze({
810				...snapshot.adoptedGeneration,
811				baseExpectedHead: Object.freeze({ ...snapshot.adoptedGeneration.baseExpectedHead }),
812				closure: Object.freeze(snapshot.adoptedGeneration.closure.map((reference) => Object.freeze({ ...reference }))),
813			}),
814			references: Object.freeze(snapshot.references.map((reference) => Object.freeze({ ...reference }))),
815		});
816	}
