832	/**
833	 * Creates the store and exact live-connection probes used by the package-local RED.
834	 * @param options - File-backed SQLite options.
835	 * @param fault - Optional bounded test-only fault callback.
836	 * @param crashObserver - Optional expanded process-death checkpoint observer.
837	 * @returns Store and non-exported connection instrumentation.
838	 * @internal
839	 */
840	export function createInstrumentedSqliteScaffold(
841		options: SqliteAheDurableStoreOptions,
842		fault?: SqliteMutationFault,
843		crashObserver?: SqliteCrashCheckpointObserver
844	): SqliteScaffoldInstrumentation {
845		const connection = new DatabaseSync(options.filename);
846		try {
847			configureConnection(connection);
