849			connection.close();
850			throw error;
851		}
852		return {
853			attemptInvalidForeignKeyInsert: (): void => {
854				connection.exec(
855					"CREATE TEMP TABLE phase_2c_parent(id INTEGER PRIMARY KEY);" +
856						"CREATE TEMP TABLE phase_2c_child(parent_id INTEGER REFERENCES phase_2c_parent(id));"
857				);
