860				} finally {
861					connection.exec("DROP TABLE phase_2c_child;DROP TABLE phase_2c_parent;");
862				}
863			},
864			readPragma: (pragma): unknown => {
865				const row = connection.prepare(`PRAGMA ${pragma}`).get();
866				return row === undefined ? undefined : Object.values(row)[0];
867			},
868			store: new SqliteAheDurableStore(connection, fault, crashObserver),
